-- GAADHE KOSHA (ಗಾದೆ ಕೋಶ) - PROVERB SEED BATCH 6
-- Records: 2501 to 2868 of 2868
-- ====================================================================

INSERT INTO public.proverbs (
    kannada, transliteration, english_meaning, kannada_meaning,
    category, category_kn, situation, situation_kn, tags, contributor, likes, is_verified
) VALUES
    ('ಬೆಳ್ಳಗಿರೋದೆಲ್ಲ ಹಾಲಲ್ಲ', 'Bellagiroodella haalalla', '[Translation in progress] Traditional folk wisdom: "ಬೆಳ್ಳಗಿರೋದೆಲ್ಲ ಹಾಲಲ್ಲ". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಬೆಳ್ಳಗಿರೋದೆಲ್ಲ ಹಾಲಲ್ಲ". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಬೆಳ್ಳಗಿರೋದೆಲ್ಲ","ಹಾಲಲ್ಲ","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಹರ್ಷದ ಕೂಳು ನೆಚ್ಚಿಕೊಂಡು ವರ್ಷದ ಕೂಳು ತಪ್ಪಿಸ್ಕೊಂಡ', 'Harshada koolu nechchikomdu varshada koolu tappiskomda', '[Translation in progress] Traditional folk wisdom: "ಹರ್ಷದ ಕೂಳು ನೆಚ್ಚಿಕೊಂಡು ವರ್ಷದ ಕೂಳು ತಪ್ಪಿಸ್ಕೊಂಡ". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಹರ್ಷದ ಕೂಳು ನೆಚ್ಚಿಕೊಂಡು ವರ್ಷದ ಕೂಳು ತಪ್ಪಿಸ್ಕೊಂಡ". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಹರ್ಷದ","ಕೂಳು","ನೆಚ್ಚಿಕೊಂಡು","ವರ್ಷದ","ತಪ್ಪಿಸ್ಕೊಂಡ","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಏರಿದವ ಇಳಿದಾನು ಏಳರಲ್ಲಿ ಬರಲೋ? ಎಪ್ಪತ್ತರಲ್ಲಿ ಬರಲೋ', 'Eeridava ilidaanu eelaralli baraloo? eppattaralli baraloo', '[Translation in progress] Traditional folk wisdom: "ಏರಿದವ ಇಳಿದಾನು ಏಳರಲ್ಲಿ ಬರಲೋ? ಎಪ್ಪತ್ತರಲ್ಲಿ ಬರಲೋ". Context: Guidance on money and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಏರಿದವ ಇಳಿದಾನು ಏಳರಲ್ಲಿ ಬರಲೋ? ಎಪ್ಪತ್ತರಲ್ಲಿ ಬರಲೋ". ಇದು ಹಣಕಾಸು ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'money', 'ಹಣಕಾಸು', 'Used in daily conversations to illustrate money principles and life lessons.', 'ಹಣಕಾಸು ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಏರಿದವ","ಇಳಿದಾನು","ಏಳರಲ್ಲಿ","ಬರಲೋ","ಎಪ್ಪತ್ತರಲ್ಲಿ","ಹಣಕಾಸು"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಕೊಟ್ಟದ್ದು ತನಗೆ, ಬಚ್ಚಿಟ್ಟಿದ್ದು ಪರರಿಗೆ', 'Kottaddu tanage, bachchittiddu pararige', '[Translation in progress] Traditional folk wisdom: "ಕೊಟ್ಟದ್ದು ತನಗೆ, ಬಚ್ಚಿಟ್ಟಿದ್ದು ಪರರಿಗೆ". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಕೊಟ್ಟದ್ದು ತನಗೆ, ಬಚ್ಚಿಟ್ಟಿದ್ದು ಪರರಿಗೆ". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಕೊಟ್ಟದ್ದು","ತನಗೆ","ಬಚ್ಚಿಟ್ಟಿದ್ದು","ಪರರಿಗೆ","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಕೆಟ್ಟ ಮೇಲೆ ಬುದ್ಧಿ ಬಂತು,ಅತ್ತ ಮೇಲೆ ಒಲೆ ಉರಿಯಿತು', 'Ketta meele buddhi bamtu,atta meele ole uriyitu', '[Translation in progress] Traditional folk wisdom: "ಕೆಟ್ಟ ಮೇಲೆ ಬುದ್ಧಿ ಬಂತು,ಅತ್ತ ಮೇಲೆ ಒಲೆ ಉರಿಯಿತು". Context: Guidance on education and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಕೆಟ್ಟ ಮೇಲೆ ಬುದ್ಧಿ ಬಂತು,ಅತ್ತ ಮೇಲೆ ಒಲೆ ಉರಿಯಿತು". ಇದು ಶಿಕ್ಷಣ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'education', 'ಶಿಕ್ಷಣ', 'Used in daily conversations to illustrate education principles and life lessons.', 'ಶಿಕ್ಷಣ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಕೆಟ್ಟ","ಮೇಲೆ","ಬುದ್ಧಿ","ಬಂತುಅತ್ತ","ಒಲೆ","ಶಿಕ್ಷಣ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಅಡಿಕೆಕಾಯಿಯನ್ನು ಚೀಲದೊಳಗೆ ಹಾಕಬಹುದು, ಮರ ಆದ ನಂತರ ಹಾಕಬಹುದೇ', 'Adikekaayiyannu cheeladolage haakabahudu, mara aada namtara haakabahudee', '[Translation in progress] Traditional folk wisdom: "ಅಡಿಕೆಕಾಯಿಯನ್ನು ಚೀಲದೊಳಗೆ ಹಾಕಬಹುದು, ಮರ ಆದ ನಂತರ ಹಾಕಬಹುದೇ". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಅಡಿಕೆಕಾಯಿಯನ್ನು ಚೀಲದೊಳಗೆ ಹಾಕಬಹುದು, ಮರ ಆದ ನಂತರ ಹಾಕಬಹುದೇ". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಅಡಿಕೆಕಾಯಿಯನ್ನು","ಚೀಲದೊಳಗೆ","ಹಾಕಬಹುದು","ನಂತರ","ಹಾಕಬಹುದೇ","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಅಪಕೀರ್ತಿ ತರುವ ಮಗನಿಗಿಂತ, ಸತ್ಕೀರ್ತಿ ತರುವ ಆಳೇ ಮೇಲು', 'Apakeerti taruva maganigimta, satkeerti taruva aalee meelu', '[Translation in progress] Traditional folk wisdom: "ಅಪಕೀರ್ತಿ ತರುವ ಮಗನಿಗಿಂತ, ಸತ್ಕೀರ್ತಿ ತರುವ ಆಳೇ ಮೇಲು". Context: Guidance on family and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಅಪಕೀರ್ತಿ ತರುವ ಮಗನಿಗಿಂತ, ಸತ್ಕೀರ್ತಿ ತರುವ ಆಳೇ ಮೇಲು". ಇದು ಕುಟುಂಬ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'family', 'ಕುಟುಂಬ', 'Used in daily conversations to illustrate family principles and life lessons.', 'ಕುಟುಂಬ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಅಪಕೀರ್ತಿ","ತರುವ","ಮಗನಿಗಿಂತ","ಸತ್ಕೀರ್ತಿ","ಆಳೇ","ಕುಟುಂಬ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ದೈವ ಕಾಡುವುವಿಧಿಗಾಗಿ, ನೀರು ಸಮುದ್ರ ಸೇರುವುದು ನದಿಗಾಗಿ', 'Daiva kaaduvuvidhigaagi, neeru samudra seeruvudu nadigaagi', '[Translation in progress] Traditional folk wisdom: "ದೈವ ಕಾಡುವುವಿಧಿಗಾಗಿ, ನೀರು ಸಮುದ್ರ ಸೇರುವುದು ನದಿಗಾಗಿ". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ದೈವ ಕಾಡುವುವಿಧಿಗಾಗಿ, ನೀರು ಸಮುದ್ರ ಸೇರುವುದು ನದಿಗಾಗಿ". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ದೈವ","ಕಾಡುವುವಿಧಿಗಾಗಿ","ನೀರು","ಸಮುದ್ರ","ಸೇರುವುದು","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಪಂಗಡವಾದವ ಸಂಗಡ ಬಂದಾನೆ', 'Pamgadavaadava samgada bamdaane', '[Translation in progress] Traditional folk wisdom: "ಪಂಗಡವಾದವ ಸಂಗಡ ಬಂದಾನೆ". Context: Guidance on money and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಪಂಗಡವಾದವ ಸಂಗಡ ಬಂದಾನೆ". ಇದು ಹಣಕಾಸು ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'money', 'ಹಣಕಾಸು', 'Used in daily conversations to illustrate money principles and life lessons.', 'ಹಣಕಾಸು ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಪಂಗಡವಾದವ","ಸಂಗಡ","ಬಂದಾನೆ","ಹಣಕಾಸು"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಬಾನ ಹರಿದು ಬೀಳುವಾಗ ಅಂಗೈ ಒಡ್ಡಿದರೆ ತಡದೀತೆ', 'Baana haridu beeluvaaga amgai oddidare tadadeete', '[Translation in progress] Traditional folk wisdom: "ಬಾನ ಹರಿದು ಬೀಳುವಾಗ ಅಂಗೈ ಒಡ್ಡಿದರೆ ತಡದೀತೆ". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಬಾನ ಹರಿದು ಬೀಳುವಾಗ ಅಂಗೈ ಒಡ್ಡಿದರೆ ತಡದೀತೆ". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಬಾನ","ಹರಿದು","ಬೀಳುವಾಗ","ಅಂಗೈ","ಒಡ್ಡಿದರೆ","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಕಂಚು ಕಡೆಯಲ್ಲ, ಹಂಚು ದ್ರವ್ಯವಲ್ಲ', 'Kamchu kadeyalla, hamchu dravyavalla', '[Translation in progress] Traditional folk wisdom: "ಕಂಚು ಕಡೆಯಲ್ಲ, ಹಂಚು ದ್ರವ್ಯವಲ್ಲ". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಕಂಚು ಕಡೆಯಲ್ಲ, ಹಂಚು ದ್ರವ್ಯವಲ್ಲ". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಕಂಚು","ಕಡೆಯಲ್ಲ","ಹಂಚು","ದ್ರವ್ಯವಲ್ಲ","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಹಚ್ಚಗಿದ್ದ ಕಡೆ ಮೇಯುವುದು ಬೆಚ್ಚಗಿದ್ದ ಕಡೆ ಮಲಗುವುದು', 'Hachchagidda kade meeyuvudu bechchagidda kade malaguvudu', '[Translation in progress] Traditional folk wisdom: "ಹಚ್ಚಗಿದ್ದ ಕಡೆ ಮೇಯುವುದು ಬೆಚ್ಚಗಿದ್ದ ಕಡೆ ಮಲಗುವುದು". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಹಚ್ಚಗಿದ್ದ ಕಡೆ ಮೇಯುವುದು ಬೆಚ್ಚಗಿದ್ದ ಕಡೆ ಮಲಗುವುದು". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಹಚ್ಚಗಿದ್ದ","ಕಡೆ","ಮೇಯುವುದು","ಬೆಚ್ಚಗಿದ್ದ","ಮಲಗುವುದು","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಹಸಿದವನಿಗೆ ಹಳಸಿದ್ದೇ ಪಾವನ', 'Hasidavanige halasiddee paavana', '[Translation in progress] Traditional folk wisdom: "ಹಸಿದವನಿಗೆ ಹಳಸಿದ್ದೇ ಪಾವನ". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಹಸಿದವನಿಗೆ ಹಳಸಿದ್ದೇ ಪಾವನ". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಹಸಿದವನಿಗೆ","ಹಳಸಿದ್ದೇ","ಪಾವನ","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಮೋಕ್ಷಕ್ಕೆ ಜ್ಞಾನ ಬೇಕು ಯೋಗಕ್ಕೆ ಧ್ಯಾನ ಬೇಕು', 'Mookshakke jnyaana beeku yoogakke dhyaana beeku', '[Translation in progress] Traditional folk wisdom: "ಮೋಕ್ಷಕ್ಕೆ ಜ್ಞಾನ ಬೇಕು ಯೋಗಕ್ಕೆ ಧ್ಯಾನ ಬೇಕು". Context: Guidance on education and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಮೋಕ್ಷಕ್ಕೆ ಜ್ಞಾನ ಬೇಕು ಯೋಗಕ್ಕೆ ಧ್ಯಾನ ಬೇಕು". ಇದು ಶಿಕ್ಷಣ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'education', 'ಶಿಕ್ಷಣ', 'Used in daily conversations to illustrate education principles and life lessons.', 'ಶಿಕ್ಷಣ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಮೋಕ್ಷಕ್ಕೆ","ಜ್ಞಾನ","ಬೇಕು","ಯೋಗಕ್ಕೆ","ಧ್ಯಾನ","ಶಿಕ್ಷಣ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
